with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'معايرة أجهزة الأرصاد والمترولوجيا وضمان جودة القياس','المترولوجيا وعدم اليقين ومعايرة حساسات الحرارة والرطوبة والضغط والرياح والهطول والإشعاع والرؤية وصيانة الشبكات.',24,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أسس المعايرة والمترولوجيا',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'معايرة حساسات عناصر الطقس',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'معايرة أجهزة الهطول والإشعاع',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تشغيل وصيانة شبكات الرصد',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('meteorological-metrology-and-measurement-uncertainty','المترولوجيا الجوية وعدم اليقين في القياس','التتبعية المترولوجية ودقة القياس ومصادر عدم اليقين.','{"blocks":[{"type":"text","text":"المترولوجيا علم القياس ويشمل الوحدات والطرق والمعايير وعدم اليقين والتتبعية."},{"type":"text","text":"التتبعية المترولوجية تعني إمكانية ربط نتيجة القياس بمرجع معياري عبر سلسلة موثقة من المعايرات."},{"type":"text","text":"الدقة Accuracy تصف قرب النتيجة من القيمة المرجعية، بينما الضبط Precision يصف تقارب القياسات المتكررة."},{"type":"text","text":"قد تنتج أخطاء القياس من الحساس والمعايرة والبيئة والتركيب والقراءة والمعالجة الرقمية."},{"type":"text","text":"يتكون عدم اليقين من مساهمات متعددة، وقد تصنف إلى تقييم إحصائي من النوع A أو تقييم بطرق أخرى من النوع B وفق الدليل المعتمد."},{"type":"text","text":"تؤثر دقة المرجع المعياري واستقرار الجهاز وطريقة المعايرة في عدم اليقين النهائي."},{"type":"text","text":"يجب تحديد مجال القياس والدقة المطلوبة وزمن الاستجابة والظروف البيئية قبل اختيار الحساس."},{"type":"text","text":"لا تعني زيادة عدد المنازل العشرية أن القياس أصبح أدق؛ إذ يجب أن تتناسب الدقة المعروضة مع عدم اليقين."},{"type":"text","text":"تسجل شهادة المعايرة الجهاز والمرجع والنتائج والتاريخ والظروف وعدم اليقين وأي تصحيحات."},{"type":"text","text":"تساعد المقارنات بين الأجهزة والمحطات على كشف الانحياز والانجراف عبر الزمن."},{"type":"text","text":"مثال: إذا كان عدم يقين حساس الحرارة أكبر من فرق الحرارة المراد دراسته، فقد لا يكون الجهاز مناسباً لهذا الغرض."},{"type":"callout","text":"خلاصة: الثقة في القياس تعتمد على سلسلة تتبعية وتقدير عدم اليقين والتوثيق المستمر."}]}',1660,55,'["تعريف التتبعية المترولوجية","تمييز الدقة عن الضبط","تقدير مصادر عدم اليقين"]','أسس المعايرة والمترولوجيا'),
('temperature-sensor-calibration-and-response','معايرة حساسات الحرارة وزمن الاستجابة','مبادئ المعايرة الحرارية والانحراف والاستقرار والاستجابة الزمنية.','{"blocks":[{"type":"text","text":"تستخدم حساسات الحرارة تقنيات مختلفة مثل المقاومة الحرارية RTD والثرمستور والمزدوج الحراري."},{"type":"text","text":"تربط المعايرة قراءة الحساس بدرجات مرجعية معروفة ضمن مجال حراري محدد."},{"type":"text","text":"قد يظهر انحياز ثابت أو تغير في الانحياز مع درجة الحرارة، لذلك تفحص عدة نقاط ضمن المجال التشغيلي."},{"type":"text","text":"يعبر زمن الاستجابة عن الوقت اللازم للحساس للاقتراب من قيمة جديدة بعد تغير درجة الحرارة المحيطة."},{"type":"text","text":"تؤثر كتلة الحساس وغطاؤه والتهوية والإشعاع في الاستجابة والقراءة الفعلية."},{"type":"text","text":"قد يؤدي التعرض المباشر للشمس أو ضعف التهوية إلى قراءة أعلى من حرارة الهواء القياسية."},{"type":"text","text":"تستخدم حواجز الإشعاع والتهوية المناسبة لتقليل أثر الإشعاع المباشر والحرارة المحيطة."},{"type":"text","text":"يجب مقارنة الحساس بمرجع مناسب مع توثيق موضع الحساس والارتفاع وظروف الاختبار."},{"type":"text","text":"تراجع المعايرة بعد الصيانة أو الاستبدال أو ظهور انحراف غير طبيعي في السجل."},{"type":"text","text":"ينبغي الاحتفاظ ببيانات ما قبل التصحيح وما بعده وسجل الصيانة والمعايرة."},{"type":"text","text":"مثال: حساس بطيء الاستجابة قد يقلل من تمثيل التغيرات السريعة في الحرارة أثناء مرور جبهة."},{"type":"callout","text":"خلاصة: جودة قياس الحرارة تعتمد على نوع الحساس والمعايرة والتعرض وزمن الاستجابة."}]}',1670,55,'["شرح معايرة حساسات الحرارة","فهم زمن الاستجابة","تفسير الانحراف الحراري"]','معايرة حساسات عناصر الطقس'),
('humidity-sensor-calibration-and-hygrometry','معايرة حساسات الرطوبة ومبادئ القياس السيكرومتري','الرطوبة النسبية ونقطة الندى ومعايرة الحساسات وقيود القياس.','{"blocks":[{"type":"text","text":"تصف الرطوبة النسبية نسبة ضغط بخار الماء الفعلي إلى ضغط الإشباع عند درجة الحرارة نفسها."},{"type":"text","text":"تعبر نقطة الندى عن درجة الحرارة التي يصل عندها الهواء إلى الإشباع عند ضغط بخار ثابت تقريباً."},{"type":"text","text":"تستخدم حساسات سعوية لقياس تغير الخصائص الكهربائية مع الرطوبة، بينما تعتمد أجهزة أخرى على مبادئ مختلفة."},{"type":"text","text":"تتأثر دقة حساسات الرطوبة بدرجة الحرارة والتلوث والتكاثف والشيخوخة والانجراف."},{"type":"text","text":"تتطلب المعايرة نقاطاً مرجعية متعددة للرطوبة ضمن مجال التشغيل المتوقع."},{"type":"text","text":"قد يظهر تأخر في استجابة الحساس عند الانتقال بين بيئات جافة ورطبة."},{"type":"text","text":"يجب تجنب التكاثف غير المقصود على الحساس لأنه قد يسبب قراءات غير مستقرة أو تغيراً مؤقتاً في الاستجابة."},{"type":"text","text":"تستخدم المراجع الرطوبية وطرق المقارنة المعتمدة لتحديد الانحياز وعدم اليقين."},{"type":"text","text":"تساعد المقارنة مع نقطة الندى أو أجهزة مرجعية على كشف اختلافات القياس."},{"type":"text","text":"ينبغي توثيق درجة الحرارة المصاحبة للرطوبة لأن تفسير الرطوبة النسبية يعتمد عليها."},{"type":"text","text":"مثال: قد تتغير الرطوبة النسبية بوضوح عند تغير الحرارة حتى إذا بقيت كمية بخار الماء قريبة من الثبات."},{"type":"callout","text":"خلاصة: معايرة الرطوبة تحتاج مرجعاً مناسباً ومراعاة الحرارة والتكاثف وزمن الاستجابة."}]}',1680,55,'["تمييز متغيرات الرطوبة","شرح معايرة الحساس","فهم أثر الحرارة والتلوث"]','معايرة حساسات عناصر الطقس'),
('barometer-calibration-and-pressure-reference','معايرة البارومترات والمراجع الضغطية','المعايرة والتحقق من الضغط المطلق والانحياز والتغير مع الارتفاع.','{"blocks":[{"type":"text","text":"تقيس البارومترات الضغط الجوي باستخدام عناصر ميكانيكية أو إلكترونية مثل الحساسات السعوية."},{"type":"text","text":"تربط المعايرة قراءة الجهاز بمرجع ضغط معتمد ضمن مجال القياس التشغيلي."},{"type":"text","text":"يجب التمييز بين الضغط المقاس عند مستوى المحطة والضغط المخفض إلى مستوى مرجعي مثل متوسط سطح البحر."},{"type":"text","text":"قد تتأثر الحساسات الإلكترونية بدرجة الحرارة والانجراف والتغيرات طويلة الأمد في خصائص العنصر الحساس."},{"type":"text","text":"تستخدم غرف أو مراجع ضغط مناسبة لإجراء المقارنات ضمن نقاط متعددة."},{"type":"text","text":"يجب توثيق اتجاه التغير والضغط المرجعي والوحدة المستخدمة أثناء الاختبار."},{"type":"text","text":"تؤثر أخطاء الارتفاع ومعلومات المحطة في تحويل الضغط إلى مستوى مرجعي."},{"type":"text","text":"يجب عدم الخلط بين QFE وQNH وQFF؛ فلكل منها تعريف واستخدام تشغيلي مختلف."},{"type":"text","text":"تستخدم قراءات المحطات المجاورة والخرائط لتحري الانحرافات غير المنطقية، دون اعتبارها بديلاً للمعايرة."},{"type":"text","text":"يساعد سجل الصيانة على تحديد توقيت الانجراف أو التغير المفاجئ في القراءة."},{"type":"text","text":"مثال: اختلاف قراءة محطة عن المحطات المحيطة يستدعي فحص التوقيت والارتفاع والمرجع والحساس قبل تعديل القيمة."},{"type":"callout","text":"خلاصة: معايرة الضغط تتطلب مرجعاً موثقاً وفهماً دقيقاً لمستوى الضغط وتحويلاته."}]}',1690,55,'["شرح معايرة حساسات الضغط","تمييز الضغط المطلق والمرجعي","فهم أثر الارتفاع والحرارة"]','معايرة حساسات عناصر الطقس'),
('wind-sensor-calibration-and-exposure','معايرة أجهزة الرياح وشروط التعرض','قياس السرعة والاتجاه والهبات وتأثير ارتفاع الحساس والعوائق.','{"blocks":[{"type":"text","text":"تقاس سرعة الرياح بأجهزة الكؤوس أو المراوح أو الحساسات فوق الصوتية وفق مبدأ كل جهاز."},{"type":"text","text":"يقيس دوار الرياح اتجاه حركة الهواء، بينما قد توفر الحساسات فوق الصوتية مركبات متجه الرياح مباشرة."},{"type":"text","text":"تحتاج معايرة السرعة إلى مرجع مناسب وفحص الاستجابة ضمن نطاقات مختلفة."},{"type":"text","text":"يجب التحقق من محاذاة اتجاه الحساس مع الشمال المرجعي وتوثيق طريقة تحديد الشمال."},{"type":"text","text":"يؤثر ارتفاع الحساس فوق السطح وخشونة المنطقة والعوائق في القيمة المرصودة."},{"type":"text","text":"قد يؤدي وجود مبنى أو شجرة قريبة إلى اضطراب محلي يجعل القياس غير ممثل للرياح العامة."},{"type":"text","text":"تستخدم معايير التعرض ارتفاعات ومناطق خلو من العوائق وفق نوع المحطة والغرض من القياس."},{"type":"text","text":"تختلف الهبة عن المتوسط في مدة القياس والتعريف، ويجب توثيق إعدادات التسجيل."},{"type":"text","text":"قد تتجمد الأجزاء المتحركة أو تتراكم عليها الأتربة والملوثات، ما يؤثر في الاستجابة."},{"type":"text","text":"تساعد المقارنة مع محطة مرجعية أو جهاز مستقل في اكتشاف الانحرافات."},{"type":"text","text":"مثال: محطة داخل فناء محاط بالمباني قد تسجل رياحاً أقل أو متغيرة الاتجاه مقارنة بموقع مفتوح قريب."},{"type":"callout","text":"خلاصة: جودة الرياح تعتمد على الحساس والمعايرة والارتفاع والتعرض والصيانة."}]}',1700,55,'["تمييز حساسات الرياح","فهم شروط التعرض","تقييم أثر العوائق"]','معايرة حساسات عناصر الطقس'),
('precipitation-gauge-calibration-and-undercatch','معايرة مقاييس المطر والثلج وفقد الهطول','التحقق الحجمي والوزني وتأثير الرياح والثلوج على التقاط الهطول.','{"blocks":[{"type":"text","text":"تستخدم مقاييس المطر القلابية والوزنية وأنظمة أخرى لقياس الهطول المتراكم أو معدل سقوطه."},{"type":"text","text":"تحتاج معايرة المقياس إلى التحقق من حجم الماء المقاس مقارنة بحجم مرجعي معروف ضمن إجراءات معتمدة."},{"type":"text","text":"قد يتأثر المقياس القلابي بشدة المطر بسبب زمن تفريغ القلاب ودقة حجم كل قلبة."},{"type":"text","text":"تستخدم المقاييس الوزنية لقياس تغير الكتلة مع الزمن، وقد توفر معلومات عن شدة الهطول وتراكمه."},{"type":"text","text":"تؤدي الرياح حول فتحة المقياس إلى اضطراب تدفق الهواء وقد تسبب نقص التقاط المطر أو الثلج."},{"type":"text","text":"يكون نقص التقاط الثلوج غالباً أكبر بسبب خفة البلورات وتأثر مسارها بالرياح."},{"type":"text","text":"تساعد الحواجز الهوائية المصممة للمقاييس على تقليل بعض آثار الرياح وفق مواصفات التركيب."},{"type":"text","text":"يجب تسوية المقياس والتحقق من نظافة الفتحة والتصريف وعدم وجود تسرب أو انسداد."},{"type":"text","text":"تحتاج قياسات الثلج إلى أدوات وطرق منفصلة لقياس العمق ومكافئ الماء عند الحاجة."},{"type":"text","text":"تؤثر فترة التجميع والتوقيت وطريقة تسجيل الأثر في مقارنة بيانات المحطات والرادار."},{"type":"text","text":"مثال: قد يسجل مقياس مكشوف للرياح كمية ثلج أقل من الكمية الفعلية بسبب نقص الالتقاط."},{"type":"callout","text":"خلاصة: معايرة الهطول تتطلب التمييز بين أداء الجهاز وأثر الموقع والرياح ونوع الهطول."}]}',1710,55,'["شرح طرق قياس الهطول","فهم فقد الالتقاط","التمييز بين المطر والثلج"]','معايرة أجهزة الهطول والإشعاع'),
('radiation-sensor-calibration-and-maintenance','معايرة أجهزة الإشعاع وصيانتها','البيرانومتر والبيرهيليومتر والحساسات الحرارية والتحقق من الاستجابة.','{"blocks":[{"type":"text","text":"يقيس البيرانومتر الإشعاع الشمسي الكلي الساقط على سطح وفق هندسة تركيبه."},{"type":"text","text":"يقيس البيرهيليومتر الإشعاع الشمسي المباشر باستخدام توجيه نحو قرص الشمس."},{"type":"text","text":"تستخدم أجهزة أخرى لقياس الإشعاع طويل الموجة أو مكونات الميزانية الإشعاعية."},{"type":"text","text":"تتأثر القراءة باستجابة الجهاز الطيفية والزاوية والحرارة ونظافة القبة ومستوى التركيب."},{"type":"text","text":"تحتاج المعايرة إلى مرجع إشعاعي معتمد ومقارنة ضمن ظروف موثقة."},{"type":"text","text":"قد يؤدي الغبار أو قطرات الماء أو تكاثف الرطوبة على القبة إلى تغيير الإشارة المقاسة."},{"type":"text","text":"يجب فحص التسوية الأفقية والتوجيه وخلو مجال الرؤية من الظلال والعوائق."},{"type":"text","text":"تحتاج الأجهزة إلى تنظيف وفحص دوري وتوثيق حالة المجفف أو التهوية عند وجودها."},{"type":"text","text":"قد تظهر فروق بين الأجهزة بسبب اختلاف الاستجابة الطيفية أو التوقيت أو المعايرة أو ظروف الموقع."},{"type":"text","text":"تستخدم المقارنة مع أجهزة مرجعية ومنتجات إشعاعية أخرى لتقييم الأداء."},{"type":"text","text":"مثال: ظل مبنى على البيرانومتر في ساعات الصباح قد يسبب انخفاضاً غير حقيقي في الإشعاع المقاس."},{"type":"callout","text":"خلاصة: قياس الإشعاع حساس للتركيب والنظافة والمعايرة والظروف البصرية للموقع."}]}',1720,55,'["تمييز أجهزة الإشعاع","شرح المعايرة والاستجابة الطيفية","فهم الصيانة الدورية"]','معايرة أجهزة الهطول والإشعاع'),
('visibility-and-present-weather-sensor-calibration','معايرة حساسات الرؤية والطقس الحالي','مقاييس الرؤية ومجسات الطقس الحالي وتفسير الاستجابة التشغيلية.','{"blocks":[{"type":"text","text":"تستخدم أجهزة قياس الرؤية مبدأ تشتت الضوء أو انتقاله لتقدير مدى الرؤية وفق هندسة القياس."},{"type":"text","text":"تختلف الرؤية المقاسة آلياً عن التقدير البصري البشري، وقد تتأثر بحجم الجسيمات وتوزيعها وتركيبها."},{"type":"text","text":"تستخدم حساسات الطقس الحالي خصائص الإشارة أو الجسيمات لتصنيف بعض الظواهر مثل المطر والثلج والرذاذ."},{"type":"text","text":"تحتاج الأجهزة إلى معايرة وفحص للمصدر الضوئي والمستقبل البصري ومحاذاة المسار."},{"type":"text","text":"تؤثر قطرات الماء والأوساخ والعناكب والملوثات على الأسطح البصرية في دقة القياس."},{"type":"text","text":"قد تختلف الرؤية على مسافات قصيرة، لذلك يجب اختيار موقع ممثل للغرض التشغيلي."},{"type":"text","text":"تستخدم المحطات تقارير بشرية أو مرئية للمقارنة والتحقق من تصنيف الحساس الآلي."},{"type":"text","text":"تتطلب حالات الضباب والرذاذ والغبار تمييزاً دقيقاً لأن خصائص الجسيمات متباينة."},{"type":"text","text":"يجب توثيق ارتفاع الجهاز واتجاهه ومجال الرصد والصيانة وإعدادات المتوسط."},{"type":"text","text":"تساعد مقارنة عدة مصادر على كشف التصنيفات الخاطئة أو الانحراف في الحساس."},{"type":"text","text":"مثال: قد يصنف حساس آلي رذاذاً كثيفاً بطريقة مختلفة عن مراقب بشري، ما يتطلب مراجعة تعريفات المنتج والظروف."},{"type":"callout","text":"خلاصة: الرؤية والطقس الحالي قياسات تشغيلية تحتاج معايرة وموقعاً مناسباً وتحققاً متعدد المصادر."}]}',1730,55,'["شرح قياس مدى الرؤية","فهم حساسات الطقس الحالي","تقييم أثر موقع الجهاز"]','معايرة أجهزة الهطول والإشعاع'),
('automatic-weather-station-maintenance','صيانة محطات الأرصاد الآلية وإدارة الأعطال','خطط الفحص الوقائي والتوثيق وإدارة الحساسات والاتصالات والطاقة.','{"blocks":[{"type":"text","text":"تحتاج محطات الطقس الآلية إلى صيانة وقائية لتقليل الأعطال وضمان استمرارية القياسات."},{"type":"text","text":"تشمل خطة الصيانة فحص الحساسات والكابلات ومصدر الطاقة والاتصالات والهيكل والحماية من العوامل البيئية."},{"type":"text","text":"يجب مراجعة جودة البيانات آلياً لاكتشاف انقطاع القياس أو ثبات القيمة أو الانحراف غير المتوقع."},{"type":"text","text":"قد تنتج فجوات البيانات من انقطاع الطاقة أو فشل الاتصال أو امتلاء التخزين أو عطل الحساس."},{"type":"text","text":"يساعد وجود ذاكرة محلية على حفظ القياسات أثناء انقطاع الاتصال، وفق سعة الجهاز وآلية الاسترجاع."},{"type":"text","text":"يجب توثيق وقت بدء العطل واكتشافه ووقت الإصلاح والقطع المستبدلة وتأثيره في السجل."},{"type":"text","text":"تحتاج البطاريات والألواح الشمسية ومصادر التغذية إلى فحص وفق بيئة الموقع وظروف التشغيل."},{"type":"text","text":"تؤثر الأتربة والرطوبة والتآكل والحشرات والثلوج في أداء المحطة بحسب نوع المنطقة."},{"type":"text","text":"يجب فحص معايرة الحساس بعد الاستبدال أو الإصلاح أو ظهور انحراف واضح."},{"type":"text","text":"تساعد مؤشرات توافر البيانات ونسبة الاكتمال ومتوسط زمن الإصلاح في تقييم أداء الشبكة."},{"type":"text","text":"مثال: تكرار انقطاع الاتصال مع استمرار التخزين المحلي يشير إلى مشكلة نقل بيانات لا إلى توقف الحساس بالضرورة."},{"type":"callout","text":"خلاصة: صيانة المحطة تجمع الوقاية والتشخيص والتوثيق واستعادة البيانات والتحقق من الأداء."}]}',1740,55,'["تصميم خطة صيانة وقائية","تحديد أعطال الحساسات والاتصال","توثيق عمليات الصيانة"]','تشغيل وصيانة شبكات الرصد'),
('station-intercomparison-and-network-harmonization','المقارنة بين المحطات وتوحيد شبكات الرصد','مقارنة الأجهزة والمواقع وتوحيد الوحدات والتوقيت والتعاريف.','{"blocks":[{"type":"text","text":"تستخدم المقارنة بين المحطات لتحديد الفروق المنهجية في القياس وتقييم اتساق الشبكة."},{"type":"text","text":"قد تنتج الفروق من اختلاف الأجهزة أو ارتفاع الحساس أو التعرض أو التوقيت أو المعالجة."},{"type":"text","text":"تحتاج المقارنة إلى اختيار فترة متزامنة ومواقع مناسبة ومراعاة الاختلافات المناخية المحلية."},{"type":"text","text":"تستخدم محطات مرجعية أو أجهزة متنقلة عند الحاجة لتقييم الفروق بين الحساسات."},{"type":"text","text":"يجب توحيد الوحدات والتوقيت ومعرفات المتغيرات وفترات المتوسط والتعاريف التشغيلية."},{"type":"text","text":"قد تختلف قراءات الرياح بسبب ارتفاع الحساس أو خشونة السطح حتى إذا كانت الأجهزة سليمة."},{"type":"text","text":"قد تختلف قياسات المطر بسبب التعرض والرياح ونوع المقياس وطريقة التجميع."},{"type":"text","text":"تساعد الرسوم المزدوجة وفروق القياس والانحدار في اكتشاف الانحياز والاختلافات الموسمية."},{"type":"text","text":"يجب عدم إزالة الفروق المناخية الحقيقية عند توحيد الشبكة؛ بل تفصل عن الفروق الناتجة من القياس."},{"type":"text","text":"تحتاج إجراءات الشبكة إلى قاموس بيانات موحد وسجل للتغييرات والمعايرة ومراقبة الجودة."},{"type":"text","text":"مثال: مقارنة محطة جديدة بمحطة مرجعية خلال فترة متزامنة تساعد على تقييم الجهاز قبل دمج سجلها طويل الأمد."},{"type":"callout","text":"خلاصة: توحيد الشبكة يحسن قابلية المقارنة مع الحفاظ على الخصائص المحلية الحقيقية."}]}',1750,55,'["شرح المقارنة بين المحطات","فهم توحيد التعاريف","تقييم اتساق الشبكة"]','تشغيل وصيانة شبكات الرصد'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'أسس المعايرة والمترولوجيا' then u1.id when 'معايرة حساسات عناصر الطقس' then u2.id when 'معايرة أجهزة الهطول والإشعاع' then u3.id when 'تشغيل وصيانة شبكات الرصد' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'معايرة أجهزة الأرصاد والمترولوجيا وضمان جودة القياس',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;